source:
OPENQASM 3.0;
include "stdgates.inc";
qubit a;
qubit b;
h a;
h a;
h a;
cx a, b;

qc:
module {
  func.func @main() attributes {mqt.entry_point} {
    %q = qc.alloc : !qc.qubit
    %q_0 = qc.alloc : !qc.qubit
    qc.h %q : !qc.qubit
    qc.h %q : !qc.qubit
    qc.h %q : !qc.qubit
    qc.ctrl(%q) targets (%q_1 = %q_0) {
      qc.x %q_1 : !qc.qubit
      qc.yield
    } : {!qc.qubit}, {!qc.qubit}
    qc.dealloc %q : !qc.qubit
    qc.dealloc %q_0 : !qc.qubit
    return
  }
}

qco:
module {
  func.func @main() attributes {mqt.entry_point} {
    %q = qco.alloc : !qco.qubit
    %q_0 = qco.alloc : !qco.qubit
    %q_1 = qco.h %q : !qco.qubit
    %q_2 = qco.h %q_1 : !qco.qubit
    %q_3 = qco.h %q_2 : !qco.qubit
    %controls_out, %targets_out = qco.ctrl(%q_3) targets (%q_4 = %q_0) {
      %q_5 = qco.x %q_4 : !qco.qubit
      qco.yield %q_5 : !qco.qubit
    } : ({!qco.qubit}, {!qco.qubit})
    qco.sink %controls_out : !qco.qubit
    qco.sink %targets_out : !qco.qubit
    return
  }
}

