routing_source:
OPENQASM 3.0;
include "stdgates.inc";
qubit[3] q;
bit[3] result;
h q[0];
cx q[0], q[1];
cx q[1], q[2];
cx q[0], q[2];
result = measure q;

Triangle.source:
OPENQASM 3;
include "stdgates.inc";

bit[3] result;

rz(-3.1415926535897931) $0;
ry(1.5707963267948966) $0;
cx $0, $1;
cx $1, $2;
cx $0, $2;
result[0] = measure $0;
result[1] = measure $1;
result[2] = measure $2;

